<script>const report=@json($report);function copyReport(){navigator.clipboard.writeText(JSON.stringify(report,null,2))}function save(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click()}function downloadJson(){save(JSON.stringify(report,null,2),'security-report.json','application/json')}function downloadCsv(){const rows=[['Section','Property','Value'],['Score','value',report.score.value],['Score','grade',report.score.grade],['HTTP','status',report.http.status],...report.findings.map(f=>['Finding',f.severity+' '+f.title,f.description])];save(rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),'security-report.csv','text/csv')}</script>
